import { Agent, routeAgentRequest } from 'agents';

async function buildExport(agentName) {
  return `https://exports.example.com/${agentName}.zip`;
}

export class Chat extends Agent {
  async onMessage(connection, message) {
    if (message === 'export') {
      await this.queue('runExport', { connectionId: connection.id });
      connection.send('export started');
      return;
    }
    connection.send(`echo: ${message}`);
  }

  async runExport({ connectionId }) {
    const url = await buildExport(this.name);
    this.getConnection(connectionId)?.send(`export ready: ${url}`);
  }
}

export default {
  async fetch(request, env) {
    return (await routeAgentRequest(request, env)) ?? new Response('Not found', { status: 404 });
  },
};

import { Agent } from 'agents';
export class Chat extends Agent {
